# ---------------------------------------------------------------------------
# SIMULATED DATA GENERATOR -- sim_htn_trial
#
# IMPORTANT: This dataset is entirely SYNTHETIC. It was generated by a
# parametric simulation with set.seed() for reproducible package examples.
# It does NOT contain any real patient, any real trial result, or any
# personally identifiable information. It must NOT be used for clinical,
# regulatory, or epidemiological inference. Every help-page example in
# macodgent uses this dataset; all numbers shown in examples are simulated.
#
# Design: a two-arm, 5-site hypertension trial with 3000 participants,
# baseline / week-4 / week-8 / week-12 blood pressure, laboratory panels,
# a binary endpoint, an ordinal endpoint, time-to-event endpoints with a
# competing cause, and a matched case-control substructure.
#
# Reproduce with: Rscript data-raw/sim_htn_trial.R
# ---------------------------------------------------------------------------

set.seed(20261105)
n <- 3000L

## -- identifiers, allocation and demographics -------------------------------
id          <- seq_len(n)
site        <- factor(paste0("SITE-", sample(1:5, n, replace = TRUE,
                                             prob = c(.28, .22, .20, .17, .13))))
treatment   <- factor(sample(c("Placebo", "Active"), n, replace = TRUE),
                      levels = c("Placebo", "Active"))
# matched pairs for conditional logistic examples (2 subjects per stratum)
match_id    <- rep(seq_len(n / 2L), each = 2L)
sex         <- factor(sample(c("Female", "Male"), n, replace = TRUE,
                             prob = c(.48, .52)))
race        <- factor(sample(c("Group A", "Group B", "Group C"), n,
                             replace = TRUE, prob = c(.55, .28, .17)))
education   <- ordered(sample(c("Basic", "Secondary", "Tertiary"), n,
                              replace = TRUE, prob = c(.30, .45, .25)),
                       levels = c("Basic", "Secondary", "Tertiary"))
age         <- round(pmin(85, pmax(30, rnorm(n, 58, 11))), 1)
bmi         <- round(pmin(48, pmax(17, 26.5 + 0.06 * (age - 58) +
                                     rnorm(n, 0, 4.1))), 1)
waist_cm    <- round(38 + 2.6 * bmi - 0.35 * (age - 58) + rnorm(n, 0, 4.5), 1)
smoke       <- factor(rbinom(n, 1, 0.27), levels = 0:1,
                      labels = c("No", "Yes"))
alcohol     <- factor(rbinom(n, 1, 0.34), levels = 0:1,
                      labels = c("No", "Yes"))
exercise_hours <- round(pmax(0, rnorm(n, 2.4, 1.5)), 1)
salt_g_day  <- round(pmax(2, rnorm(n, 9.2, 2.6)), 1)
diabetes    <- factor(rbinom(n, 1, plogis(-2.3 + 0.02 * (bmi - 27))),
                      levels = 0:1, labels = c("No", "Yes"))
dyslipidemia <- factor(rbinom(n, 1, 0.31), levels = 0:1,
                       labels = c("No", "Yes"))
ckd         <- factor(rbinom(n, 1, plogis(-3.4 + 0.045 * (age - 58))),
                     levels = 0:1, labels = c("No", "Yes"))
prior_cv    <- factor(rbinom(n, 1, 0.12), levels = 0:1,
                      labels = c("No", "Yes"))
family_history <- factor(rbinom(n, 1, 0.38), levels = 0:1,
                         labels = c("No", "Yes"))

## -- blood pressure trajectory ---------------------------------------------
sbp_baseline <- round(148 + 0.30 * (age - 58) + 0.65 * (bmi - 26.5) +
                        0.55 * (salt_g_day - 9.2) +
                        3.4 * (smoke == "Yes") + 4.1 * (diabetes == "Yes") +
                        rnorm(n, 0, 11), 1)
dbp_baseline <- round(38 + 0.53 * sbp_baseline + rnorm(n, 0, 6.5), 1)
dose_level   <- ordered(sample(c("Low", "Medium", "High"), n, replace = TRUE,
                               prob = c(.35, .42, .23)),
                        levels = c("Low", "Medium", "High"))
adherence_pct <- round(pmin(100, pmax(20, rbeta(n, 9, 2) * 100)), 1)
drop         <- 13.5 * (treatment == "Active") + 2.4 * (treatment == "Placebo") +
               2.0 * (dose_level == "Medium") + 4.0 * (dose_level == "High") +
               0.06 * (adherence_pct - 85) + rnorm(n, 0, 6.5)
sbp_week4   <- round(sbp_baseline - 0.55 * drop + rnorm(n, 0, 4.5), 1)
sbp_week8   <- round(sbp_baseline - 0.85 * drop + rnorm(n, 0, 4.8), 1)
sbp_week12  <- round(sbp_baseline - drop + rnorm(n, 0, 5.0), 1)
dbp_week12  <- round(dbp_baseline - 0.48 * drop + rnorm(n, 0, 4.2), 1)
heart_rate  <- round(pmin(115, pmax(48, 72 + rnorm(n, 0, 10))), 0)

## -- laboratory panel (correlated, partly skewed) ---------------------------
ldl         <- round(118 + 0.35 * (bmi - 26.5) + rnorm(n, 0, 27), 1)
hdl         <- round(52 - 0.30 * (bmi - 26.5) - 5 * (sex == "Male") +
                       rnorm(n, 0, 11), 1)
triglycerides <- round(exp(rnorm(n, log(135), 0.36)), 1)     # right-skewed
glucose     <- round(94 + 0.55 * (bmi - 26.5) +
                       14 * (diabetes == "Yes") + rnorm(n, 0, 15), 1)
creatinine  <- round(pmax(0.5, 0.86 + 0.006 * (age - 58) +
                            0.18 * (ckd == "Yes") + rnorm(n, 0, 0.15)), 2)
egfr        <- round(pmax(18, 118 - 52 * creatinine + rnorm(n, 0, 9)), 1)
potassium   <- round(rnorm(n, 4.2, 0.42), 2)
sodium      <- round(rnorm(n, 139.5, 2.8), 1)
crp         <- round(exp(rnorm(n, log(2.4), 0.75)), 2)      # strongly skewed
urine_albumin <- round(exp(rnorm(n, log(18), 0.85)), 1)     # skewed
quality_score <- round(pmin(100, pmax(0, rnorm(n, 78, 11))), 1)

## -- endpoints ---------------------------------------------------------------
p_control <- plogis(-1.05 + 0.055 * (sbp_baseline - sbp_week12 - 8) +
                      0.45 * (treatment == "Active") -
                      0.30 * (diabetes == "Yes") +
                      0.012 * (adherence_pct - 85))
bp_control <- factor(rbinom(n, 1, p_control), levels = 0:1,
                     labels = c("No", "Yes"))
bp_grade <- ordered(
  cut(sbp_week12, breaks = c(-Inf, 120, 130, 140, Inf),
      labels = c("Normal", "Elevated", "Stage 1", "Stage 2")),
  levels = c("Normal", "Elevated", "Stage 1", "Stage 2"))
adverse_event <- factor(rbinom(n, 1, plogis(-2.6 + 0.35 *
                          (treatment == "Active"))), levels = 0:1,
                        labels = c("No", "Yes"))
compliance <- ordered(sample(c("Low", "Medium", "High"), n, replace = TRUE,
                             prob = c(.18, .40, .42)),
                      levels = c("Low", "Medium", "High"))

## -- time-to-event and competing-risk endpoints -----------------------------
lp <- 0.028 * (age - 58) + 0.011 * (sbp_baseline - 148) +
      0.42 * (diabetes == "Yes") + 0.38 * (prior_cv == "Yes") -
      0.30 * (treatment == "Active")
event_time  <- rexp(n, rate = 0.00042 * exp(lp))
death_time  <- rexp(n, rate = 0.00019 * exp(0.75 * lp))
censor_time <- 730
fu_time     <- pmin(event_time, death_time, censor_time)
followup_days <- round(pmax(1, fu_time), 0)
cv_event    <- as.integer(event_time <= censor_time & event_time <= death_time)
comp_event  <- integer(n)
comp_event[cv_event == 1L] <- 1L
comp_event[death_time <= censor_time & death_time < event_time] <- 2L

## -- matched case-control endpoint for conditional logistic regression ------
p_case <- plogis(-0.6 + 0.75 * (prior_cv == "Yes") + 0.45 * (smoke == "Yes") +
                   0.012 * (ldl - 118))
case_lp <- p_case + rnorm(n, 0, 0.12)
case_status <- integer(n)
for (s in unique(match_id)) {
  ix <- which(match_id == s)
  case_status[ix[which.max(case_lp[ix])]] <- 1L
}

## -- assemble ----------------------------------------------------------------
sim_htn_trial <- data.frame(
  id, site, match_id, treatment, dose_level, sex, race, education,
  age, bmi, waist_cm, smoke, alcohol, exercise_hours, salt_g_day,
  diabetes, dyslipidemia, ckd, prior_cv, family_history,
  sbp_baseline, dbp_baseline, sbp_week4, sbp_week8, sbp_week12,
  dbp_week12, heart_rate, ldl, hdl, triglycerides, glucose,
  creatinine, egfr, potassium, sodium, crp, urine_albumin,
  adherence_pct, quality_score, bp_control, bp_grade, adverse_event,
  compliance, followup_days, cv_event, comp_event, case_status,
  stringsAsFactors = FALSE)

## -- MCAR missingness for imputation / audit examples ------------------------
set.seed(991)
sim_htn_trial$adherence_pct[sample(n, 90)]  <- NA
sim_htn_trial$quality_score[sample(n, 150)] <- NA
sim_htn_trial$potassium[sample(n, 60)]      <- NA
sim_htn_trial$urine_albumin[sample(n, 75)]  <- NA

## -- explicit provenance attributes: this is SIMULATED data -----------------
attr(sim_htn_trial, "simulated") <- TRUE
attr(sim_htn_trial, "seed")      <- 20261105L
attr(sim_htn_trial, "provenance") <- paste(
  "SYNTHETIC / SIMULATED data generated by data-raw/sim_htn_trial.R;",
  "no real patients; for package examples only;",
  "not for clinical or regulatory inference.")
attr(sim_htn_trial, "created")   <- "2026-11-05"
comment(sim_htn_trial) <- attr(sim_htn_trial, "provenance")

stopifnot(nrow(sim_htn_trial) == 3000L, ncol(sim_htn_trial) >= 30L,
          isTRUE(attr(sim_htn_trial, "simulated")))
dir.create("data", showWarnings = FALSE)
save(sim_htn_trial, file = "data/sim_htn_trial.rda",
     compress = "xz", version = 2)
cat("simulated sim_htn_trial:", nrow(sim_htn_trial), "rows x",
    ncol(sim_htn_trial), "columns\n")
